/*
  dfdl tokens. Single source of truth for the design standard.

  Two tiers:
    primitives  named by hue and step (--neutral-light-3, --accent-dark-9). Never used in components.
    semantics   named by role (--bg-surface, --fg-secondary, --border-default, --accent-solid).
                The only tier components touch, through the Tailwind utilities in globals.css.

  Light and dark repoint the semantic tier; primitives stay fixed.

  Naming grammar for semantics: --{group}-{variant}-{state}
    bg        page, subtle, surface, surface-hover, surface-active, sunken, raised, overlay
    fg        default (--fg), secondary, tertiary, strong, disabled, inverse, on-accent
    border    subtle, default, strong, separator, focus
    accent    bg, border, solid, solid-hover, text
    status    danger, success, warning (bg, border, solid, text)
    rounded   xs, sm, md, lg, xl, full
    motion    ease-out, ease-in-out, ease-drawer, ease-spring, instant, fast, normal, slow, slower,
              exit-factor, exit-scale, pop-scale, press, icon-blur
    elevation raised, floating

  Source token names never collide with Tailwind theme keys (--color-*, --radius-*, --ease-*, --shadow-*);
  globals.css maps them. A source name equal to a theme key produces a self-referential variable.

  Color is GENERATED: run `node scripts/color/build-tokens.mts` after changing the config there.
  Lab 1 (2026-09-19): unified warm neutral (hue 80), ember accent (hue 48) at 60% of its
  gamut ceiling in light and 55% in dark, ring-and-lift elevation. Status hues held 30 degrees or more from the accent.
  Lab 2 (2026-09-24): weight-led type, Lora on every heading, round radius family. Body 16 since 2026-09-25.
  Lab 3 (2026-09-24): strong ease-out, exits at 75%, press 0.97.
  Rhythm, rounded, type and motion below are hand-authored. Nothing is interim.
*/

:root {
  /* ---- Rhythm ---- */
  --space-minor: 0.5rem; /* 8px */
  --space-major: 1.5rem; /* 24px */
  --measure-reading: 33rem;
  --measure-content: 64rem;

  /* ---- Rounded (Lab 2, approved 2026-09-24: "Round"). Concentric: outer = inner + padding. ---- */
  --rounded-xs: 8px;
  --rounded-sm: 10px;
  --rounded-md: 12px;
  --rounded-lg: 16px;
  --rounded-xl: 24px;
  --rounded-full: 9999px;

  /* ---- Type roles, measured from dylanfdl.com's rendered text (2026-09-25) and chosen by Dylan to match it:
     Lora only for titles (page title 24/32, article title 28/32); headings are sans at 600 and step down by size
     (title 20, heading 17); prose 14/24 at 450, articles 15/24; interface text 14/20. ---- */
  --font-display-family: var(--font-lora), ui-serif, Georgia, serif;
  --font-heading-family: ui-sans-serif, system-ui, sans-serif;
  --type-headline-size: 1.75rem;
  --type-headline-leading: 2rem;
  --type-headline-weight: 400;
  --type-headline-tracking: 0;
  --type-display-size: 1.5rem;
  --type-display-leading: 2rem;
  --type-display-weight: 400;
  --type-display-tracking: 0;
  --type-title-size: 1.25rem;
  --type-title-leading: 2rem;
  --type-title-weight: 600;
  --type-title-tracking: 0;
  --type-heading-size: 1.0625rem;
  --type-heading-leading: 1.5rem;
  --type-heading-weight: 600;
  --type-heading-tracking: 0;
  --type-body-size: 0.875rem;
  --type-body-leading: 1.5rem;
  --type-body-weight: 450;
  --type-reading-size: 0.9375rem;
  --type-reading-leading: 1.5rem;
  --type-reading-weight: 400;
  --type-ui-size: 0.875rem;
  --type-ui-leading: 1.25rem;
  --type-ui-weight: 450;
  --type-caption-size: 0.75rem;
  --type-caption-leading: 1rem;
  --type-caption-weight: 450;
  --type-control-height: 2rem;

  /* ---- Motion (Lab 3, approved 2026-09-24) ----
     Curves: strong ease-out for enters and exits, strong ease-in-out for on-screen movement, the iOS curve for
     drawers; the spring is for gestures only. Durations by frequency: instant for tooltips, fast for hover and
     press, normal for menus and popovers, slow for dialogs, slower for drawers. Exits run at 75% of the enter
     along the same path. Press is scale 0.97. Popovers scale from their trigger; dialogs from center. ---- */
  --motion-ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --motion-ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  --motion-ease-drawer: cubic-bezier(0.32, 0.72, 0, 1);
  --motion-ease-spring: linear(0, 0.102, 0.303, 0.509, 0.681, 0.808, 0.895, 0.949, 0.98, 0.996, 1.004, 1.006, 1.006, 1.005, 1.004, 1.002, 1.001, 1.001, 1, 1, 1, 1, 1, 1, 1);
  --motion-instant: 100ms;
  --motion-fast: 150ms;
  --motion-normal: 200ms;
  --motion-slow: 300ms;
  --motion-slower: 500ms;
  --motion-exit-factor: 0.75;
  --motion-exit-scale: 1;
  --motion-press: 0.97;
  --motion-pop-scale: 0.95;
  --motion-icon-blur: 4px;
}

